<div class="search-page"><div class="pagehead"><div><span class="section-kicker">SEARCH</span><h1>جستجوی کتابخانه</h1></div><form method="get"><input name="q" value="<?=e($q)?>" autofocus placeholder="نام کتاب، مؤلف، علم یا کلیدواژه…"><button>🔎 جستجو</button></form></div><form class="search-filters" method="get"><input type="hidden" name="q" value="<?=e($q)?>"><label><input type="checkbox" name="types[]" value="books" <?=in_array('books',$types,true)?'checked':''?>> کتاب‌ها</label><label><input type="checkbox" name="types[]" value="authors" <?=in_array('authors',$types,true)?'checked':''?>> مؤلفین</label><label><input type="checkbox" name="types[]" value="categories" <?=in_array('categories',$types,true)?'checked':''?>> علوم</label><span class="muted">اگر هیچ گزینه‌ای انتخاب نشود، هر سه حوزه جستجو می‌شوند.</span><button>اعمال</button></form><?php if($q===''):?><div class="empty"><h2>جستجو را شروع کنید</h2><p>عنوان کتاب، نام مؤلف، علم یا کلیدواژه را وارد کنید.</p></div><?php else:?><section><div class="section-head"><h2>کتاب‌ها <small>(<?=count($books)?>)</small></h2></div><div class="table library-table"><div class="thead"><span>کتاب</span><span>مؤلف</span><span>بازدید</span></div><?php foreach($books as $b):?><a class="tr" href="/book?id=<?=$b['id']?>"><span><?=e($b['title'])?></span><span><?=e($b['author']??'—')?></span><span><?=number_format($b['views'])?></span></a><?php endforeach;?></div></section><section><div class="section-head"><h2>مؤلفین <small>(<?=count($authors)?>)</small></h2></div><div class="author-grid"><?php foreach($authors as $a):?><a href="/author?id=<?=$a['id']?>"><strong><?=e($a['name'])?></strong></a><?php endforeach;?></div></section><section><div class="section-head"><h2>علوم <small>(<?=count($cats)?>)</small></h2></div><div class="science-list"><?php foreach($cats as $c):?><a href="/category?id=<?=$c['id']?>"><span><?=e($c['name'])?></span></a><?php endforeach;?></div></section><?php endif;?></div>
